<form method="post" action="{{ $action }}">@csrf @if($token)@method('PUT')@endif<div class="domain-modal-body"><label class="field"><span>Token name</span><input name="name" value="{{ old('name',$token?->name) }}" required placeholder="CI / CD Deployment">@error('name')<small class="field-error">{{ $message }}</small>@enderror</label><div class="form-grid form-grid--two"><label class="field"><span>Environment</span><select name="environment">@foreach(['production','staging','development'] as $environment)<option value="{{ $environment }}" @selected(old('environment',$token?->environment??'production')===$environment)>{{ ucfirst($environment) }}</option>@endforeach</select></label><label class="field"><span>Expires</span><select name="expires_in"><option value="30">30 days</option><option value="90" selected>90 days</option><option value="365">1 year</option><option value="never" @selected($token&&!$token->expires_at)>Never</option></select></label></div><fieldset class="scope-picker"><legend>Permissions</legend>@foreach($scopes as $scope)<label><input type="checkbox" name="scopes[]" value="{{ $scope }}" @checked(in_array($scope,old('scopes',$token?->abilities??[$scopes[0]])))><span><i data-lucide="check"></i>{{ str($scope)->replace(':',': ') }}</span></label>@endforeach</fieldset><label class="field"><span>IP restrictions</span><textarea name="ip_restrictions" rows="2" placeholder="203.0.113.10, 2001:db8::1">{{ old('ip_restrictions',implode(', ',$token?->ip_restrictions??[])) }}</textarea><small>Optional comma-separated addresses.</small></label></div><div class="domain-modal-actions"><button type="button" class="button button--secondary" @click="{{ $token?'editOpen':'createOpen' }}=false">Cancel</button><button class="button button--primary">{{ $token?'Save Token':'Create Token' }}</button></div></form>
